<?php declare(strict_types='1'); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Text Cleaner','description'=>'Trim lines and normalize repeated spaces in text.','url'=>'https://smarttoolz.in/tools/text-cleaner/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Text Cleaner</h1><p>Clean extra spaces and blank lines from text.</p></section><section class="tool-workspace"><div class="tool-panel"><textarea id="i" rows="12" placeholder="Paste text..."></textarea><button id="go" class="tool-btn">Clean Text</button><textarea id="o" rows="12" readonly></textarea></div></section></main><script>go.onclick=()=>o.value=i.value.split(/\r?\n/).map(x=>x.trim().replace(/\s+/g,' ')).filter(Boolean).join('\n')</script><?php smarttoolz_tool_page_end(); ?>